// Author: MiYu. Source undead forms exercise payment and food, actual ground restrictions, recovery and buried visibility.
#include "session.h"
#include "setup.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc!=3)throw std::runtime_error("Usage: war3_undead_forms_tests <data-root> <fixture>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto number=[](jass::Real value){return std::bit_cast<float>(value.bits());};auto real=[&](float value){return vm.real(jass::Real::fromBits(std::bit_cast<std::uint32_t>(value)));};auto type=[&](const char* value){return vm.integer(int(ObjectData::code(value)));};auto player=call("Player",{vm.integer(0)});auto state=[&](unsigned key,int value){call("SetPlayerState",{player,vm.handle("playerstate",key),vm.integer(value)});};auto order=[&](jass::Value unit,const char* value){return call("IssueImmediateOrder",{unit,vm.string(value)}).bits!=0;};auto statue=vm.global("statue"),gargoyle=vm.global("gargoyle"),fiend=vm.global("fiend"),foe=vm.global("enemyUnit");auto s=session.units().at(statue.bits),g=session.units().at(gargoyle.bits),f=session.units().at(fiend.bits);auto& resources=session.config().players[0].states;
        int food=resources.at(5);state(1,99);require(!order(statue,"avengerform") && s->type==ObjectData::code("uobs") && resources.at(1)==99 && resources.at(5)==food,"Paid form accepted insufficient gold or changed state on rejection");state(1,1000);state(4,food+1);require(!order(statue,"avengerform") && resources.at(1)==1000,"Paid form accepted insufficient extra food");state(4,90);auto buttons=session.abilityCommands(statue.bits,0);auto command=std::find_if(buttons.begin(),buttons.end(),[](auto& b){return b.type==ObjectData::code("Aave");});require(command!=buttons.end() && command->gold==100 && command->lumber==50,"Destroyer source difference price was missing from its command");require(order(statue,"avengerform"),"Destroyer source order rejected");session.advance(3);require(s->type==ObjectData::code("ubsp") && s->airborne() && s->flyHeight==240 && number(s->maxLife)==900 && number(s->maxMana)==400 && number(s->mana)==0 && resources.at(1)==900 && resources.at(2)==950 && resources.at(5)==food+2,"Destroyer type, mana reset, price or extra population was not consumed exactly once");require(!order(statue,"unavengerform"),"Permanent Destroyer reversed");buttons=session.abilityCommands(statue.bits,0);require(std::none_of(buttons.begin(),buttons.end(),[](auto& b){return b.type==ObjectData::code("Aave");}),"Permanent Destroyer retained its transformation button");std::cout<<"PASS destroyer_payment_food_mana_type_and_permanent_command\n";
        require(order(gargoyle,"stoneform"),"Stone Form source order rejected");session.advance(3);require(g->type==ObjectData::code("ugrm") && !g->airborne() && g->flyHeight==0 && g->animationProperties=="Alternate" && !session.attackUnit(gargoyle.bits,foe.bits) && !call("IssuePointOrder",{gargoyle,vm.string("move"),real(512),real(256)}).bits,"Stone Form ground, animation or action restrictions missing");require(!session.castSpell(foe.bits,ObjectData::code("AHtb"),gargoyle.bits),"Stone Form accepted a non-immune target spell");call("SetWidgetLife",{gargoyle,real(100)});session.advance(2);require(number(g->life)>=115.9f,"Stone Form did not regenerate away from blight");require(!order(gargoyle,"unstoneform"),"Stone Form ignored its source cooldown");session.advance(30);require(order(gargoyle,"unstoneform"),"Stone reverse did not become available");session.advance(3);require(g->type==ObjectData::code("ugar") && g->airborne() && g->flyHeight==240 && !g->formHealthRegen,"Stone reverse did not restore the flying unit");std::cout<<"PASS stone_ground_immunity_actions_regeneration_cooldown_and_return\n";
        require(order(fiend,"burrow"),"Burrow source order rejected");session.advance(3);require(f->type==ObjectData::code("ucrm") && f->burrowed && f->animationProperties=="Alternate" && session.unitInvisible(fiend.bits) && session.unitInvisibleTo(fiend.bits,1) && !session.attackUnit(fiend.bits,foe.bits),"Burrow did not enter its real immobile invisible form");call("SetWidgetLife",{fiend,real(100)});session.advance(2);require(number(f->life)>=109.9f,"Burrow source five-point recovery was not consumed");require(call("UnitAddAbility",{foe,type("Atru")}).bits!=0,"Source Shade detection ability could not be added");require(session.unitDetected(fiend.bits,1) && !session.unitInvisibleTo(fiend.bits,1),"Burrow detection mask did not reveal the fiend");require(order(fiend,"unburrow"),"Unburrow source order rejected");session.advance(3);require(f->type==ObjectData::code("ucry") && !f->burrowed && !session.unitInvisible(fiend.bits) && f->animationProperties.empty(),"Unburrow did not restore normal visibility and type");std::cout<<"PASS burrow_type_visibility_detection_regeneration_and_return\n";
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed=3 failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
